 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = [v for row in grid for v in row if v not in (1, 6)]
    background = max(set(colors), key=colors.count)
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    # Every diagonal pair of 1 markers defines a segment to complete.
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i+1:]:
            dr, dc = r2-r1, c2-c1
            if dr != 0 and abs(dr) == abs(dc):
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                segments.append((r1, c1, r2, c2, sr, sc))
                for k in range(1, abs(dr)):
                    r, c = r1 + sr*k, c1 + sc*k
                    if grid[r][c] != 6:
                        out[r][c] = 1
    # A 6 marker lying on a completed 1-segment extends on the crossing diagonal.
    for r, c in [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]:
        for r1, c1, r2, c2, sr, sc in segments:
            if (r-r1)*(c2-c1) == (c-c1)*(r2-r1):
                # Must lie between the segment endpoints, inclusive.
                if min(r1, r2) <= r <= max(r1, r2) and min(c1, c2) <= c <= max(c1, c2):
                    step_c = -sr*sc
                    for t in range(-max(h, w), max(h, w)+1):
                        rr, cc = r+t, c+step_c*t
                        if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                            out[rr][cc] = 6
    return out
